skip_unless_full_tests()

# Rows of the docsmm battery: each R call against the string SymPy prints
# for the same call (an error as "ERR <class>: <message>").

.docsmm_env <- new.env()
evalq({
x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); s <- Symbol("s"); n <- Symbol("n"); i <- Symbol("i"); t <- Symbol("t")
EE <- Symbol("E"); II <- Symbol("I")
beam1 <- function() { b <- Beam(30, EE, II); R1 <- Symbol("R1"); R2 <- Symbol("R2")
  b$apply_load(R1, 10, -1); b$apply_load(R2, 30, -1); b$apply_load(-8, 0, -1)
  b$bc_deflection <- list(list(10, 0), list(30, 0)); b$solve_for_reaction_loads(R1, R2); b }
beam2 <- function() { b <- Beam(4, EE, II); Ra <- Symbol("R_a"); Rb <- Symbol("R_b")
  b$apply_load(Ra, 0, -1); b$apply_load(6, 2, 0); b$apply_load(Rb, 4, -1)
  b$bc_deflection <- list(list(0, 0), list(4, 0)); b$solve_for_reaction_loads(Ra, Rb); b }
Xd <- DiscreteRV(x, S(1)/2^x, set = Naturals)
MV <- MultivariateNormal("M", list(1, 2), list(list(2, 1), list(1, 2)))
MN <- MatrixNormal("M", list(list(1, 2)), list(1), list(list(1, 0), list(0, 1)))
MT <- MatrixStudentT("M", 2, list(list(1, 2)), list(list(1, 0), list(0, 1)), list(1))
XM <- MatrixSymbol("X", 1, 2)
Ms <- MatrixSymbol("Ms", 3, 3)
f <- Function("f"); g <- Function("g")
A_ <- Symbol("A"); B_ <- Symbol("B"); C_ <- Symbol("C")
pyset <- function(l) paste0("{", paste(vapply(l, sstr, ""), collapse = ", "), "}")
}, .docsmm_env)

.docsmm_run <- function(code) tryCatch({
  v <- suppressWarnings(eval(parse(text = code), .docsmm_env))
  gsub("\n", "\\n", if (inherits(v, "Poly")) paste(capture.output(print(v)), collapse = "\n") else if (is_sym(v) || inherits(v, "symmatrix")) sstr(v) else .pyfmt(v), fixed = TRUE)
}, error = function(e) {
  cl <- setdiff(class(e), c("simpleError", "error", "condition"))
  paste0("ERR ", if (length(cl)) cl[1] else "Error", ": ", paste(strsplit(trimws(conditionMessage(e)), "\\s+")[[1]], collapse = " "))
})

test_that("row 1: ArrayComprehensionMap(lambda: 1, (i, 1, 2))", expect_identical(.docsmm_run("ArrayComprehensionMap(function() 1, list(i, 1, 2))"), "ArrayComprehensionMap((i, 1, 2))"))
test_that("row 2: ArrayComprehensionMap(lambda i: i+1, (i, 1, 5)).doit()", expect_identical(.docsmm_run("doit(ArrayComprehensionMap(function(i) i + 1, list(i, 1, 5)))"), "[2, 3, 4, 5, 6]"))
test_that("row 3: ArrayDerivative(ArraySymbol(\"A\", (2, 2)), ArraySymbol(\"A\", (2, 2)))", expect_identical(.docsmm_run("ArrayDerivative(ArraySymbol(\"A\", list(2, 2)), ArraySymbol(\"A\", list(2, 2)))"), "ERR ValueError: Can't calculate derivative wrt A."))
test_that("row 5: PIDController(1, 2, 3, 0, s)", expect_identical(capture.output(print(eval(quote(PIDController(1, 2, 3, 0, s)), .docsmm_env))), "PIDController(1, 2, 3, 0, s)"))
test_that("row 6: PIDController(1, 2, 3, 0, s).doit()", expect_identical(.docsmm_run("PIDController(1, 2, 3, 0, s)$doit()"), "TransferFunction(3*s^2 + s + 2, s, s)"))
test_that("row 8: beam1().max_deflection()", expect_identical(.docsmm_run("beam1()$max_deflection()"), "(30 - 20*sqrt(3)/3, (-1512000*sqrt(3) - 12*(90 - 20*sqrt(3))^3 + 18*(60 - 20*sqrt(3))^3 + 4860000)/(243*Abs(E*I)))"))
test_that("row 10: density(Xd)(z)", expect_identical(.docsmm_run("apply_lambda(rv_density(Xd), z)"), "Piecewise((2^(-z), (z >= 1) & (z < oo) & Eq(z, floor(z))), (0, True))"))
test_that("row 11: E(Xd)", expect_identical(.docsmm_run("E(Xd)"), "Sum(Piecewise((x/2^x, (x >= 1) & Eq(x, floor(x))), (0, True)), (x, 1, oo))"))
test_that("row 12: P(Xd > 2)", expect_identical(.docsmm_run("P(Xd > 2)"), "1/4"))
test_that("row 13: density(DiscreteRV(x, S(1)/10, set=S.Integers))(z)", expect_identical(.docsmm_run("apply_lambda(rv_density(DiscreteRV(x, S(1)/10, set = Integers)), z)"), "Piecewise((1/10, (z > -oo) & (z < oo) & Eq(z, floor(z))), (0, True))"))
test_that("row 14: entropy(Die(\"D\", 6))", expect_identical(.docsmm_run("entropy(Die(\"D\", 6))"), "log(6)"))
test_that("row 15: density(MV)(x, y)", expect_identical(.docsmm_run("apply_lambda(rv_density(MV), x, y)"), "sqrt(3)*exp(-x^2/3 + x*y/3 - y^2/3 + y - 1)/(6*pi)"))
test_that("row 16: marginal_distribution(MV, 0)(x)", expect_identical(.docsmm_run("apply_lambda(marginal_distribution(MV, 0), x)"), "exp(-(x - 1)^2/4)/(2*sqrt(pi))"))
test_that("row 17: density(MN)(XM).doit()", expect_identical(.docsmm_run("doit(apply_lambda(rv_density(MN), XM))"), "exp(-Trace((Matrix([\\n[-1],\\n[-2]]) + X.T)*(Matrix([[-1, -2]]) + X))/2)/(2*pi)"))
test_that("row 18: density(MT)(XM).doit()", expect_identical(.docsmm_run("doit(apply_lambda(rv_density(MT), XM))"), "1/(pi^1.0*Determinant((Matrix([[-1, -2]]) + X)*(Matrix([\\n[-1],\\n[-2]]) + X.T) + Matrix([[1]]))^2)"))
test_that("row 19: density(MN)(Matrix([[3, 4]])).doit()", expect_identical(.docsmm_run("doit(apply_lambda(rv_density(MN), Matrix(list(list(3, 4)))))"), "exp(-4)/(2*pi)"))
test_that("row 20: density(MT)(Matrix([[3, 4]])).doit()", expect_identical(.docsmm_run("doit(apply_lambda(rv_density(MT), Matrix(list(list(3, 4)))))"), "1/(81*pi^1.0)"))
test_that("row 21: E(Multinomial(\"M\", 3, S(1)/2, S(1)/2)[0])", expect_identical(.docsmm_run("E(rv_getitem(Multinomial(\"M\", 3, S(1)/2, S(1)/2), 0))"), "ERR TypeError: use Interval or Relational, not Range"))
test_that("row 22: Result(x**2).get_datatype(\"C\")", expect_identical(.docsmm_run("ast_attr(Result(x^2), \"get_datatype\")(\"C\")"), "double"))
test_that("row 23: convolution_fft([1 + 2*I, 3 + 4*I, 5 + S(3)/5*I], [S(2)/5 + S(4)/7*I])", expect_identical(.docsmm_run("convolution_fft(list(1 + 2*sym_I, 3 + 4*sym_I, 5 + S(3)/5*sym_I), list(S(2)/5 + S(4)/7*sym_I))"), "[-26/35 + 48*I/35, -38/35 + 116*I/35, 58/35 + 542*I/175]"))
