test_that("row 27: log_to_atan(Poly(x, x, domain='EX'), Poly(1, x, domain='EX'))", expect_identical(.docsmm_run("log_to_atan(Poly(x, x, domain = \"EX\"), Poly(1, x, domain = \"EX\"))"), "2*atan(x)"))
